from knowledge_store import WORK,load_symbols,save_review
from printing_knowledge_continuation import A,record,checkpoint

def emit(path,data,scope):
 out=[]
 for s in load_symbols(path)['symbols']:
  if not s['isCallable']:continue
  reason,ins,outs,side,issues,tests,rels=data[s['startLine']]
  out.append(record(s,reason,ins,outs,side,'Production domain ticket->GDI bitmap->ESC/POS bytes or offline preview decode; no live server trust assumed','NOT_APPLICABLE: these functions have no SQL/auth/session calls','Rendering pixels/preview is distinct from transport acceptance and actual paper; no physical action performed','Per-function layout/pixel/QR complexity described; no benchmark executed','Exact stable source syntax distinguishes nested helper and lambdas; no duplicated business/payment logic here',issues,tests,rels))
 assert len(out)==len(data),(path,len(out),len(data))
 save_review(A,path,{'scope':scope,'symbols':out})
 checkpoint(path+' '+str(len(out))+' actual callables','Validate388 stable receipts and issue checkpoint; parent owns global mission progress and SEC001 flow')

